INSERT INTO nea_country_trade (fiscal_year, country, trade_status, trade_partner, trade_mechanism, export_gwh, import_gwh, export_revenue_npr_million, import_cost_npr_million, export_capacity_mw, import_capacity_mw, season_active, volume_scope, notes, data_source) VALUES
(2020, 'India', 'Active', 'NVVN / PGCIL', 'Power Exchange / Bilateral', 107, 1729, NULL, NULL, NULL, NULL, 'Year Round', 'national_total_all_destinations_split_unverified', 'Import via Dhalkebar-Muzaffarpur 400kV line. Nepal net importer.', 'NEA Annual Report 2019/20'),
(2021, 'India', 'Active', 'NVVN / PGCIL', 'Power Exchange / Bilateral', 44, 2826.21, NULL, NULL, NULL, NULL, 'Year Round', 'national_total_all_destinations_split_unverified', 'High import due to delay in Upper Tamakoshi commissioning. COVID impact on export.', 'NEA Annual Report 2020/21'),
(2022, 'India', 'Active', 'NVVN / PGCIL / IEX', 'Power Exchange / Day-Ahead Market', 493, 1543, NULL, NULL, 452, NULL, 'Year Round', 'national_total_all_destinations_split_unverified', 'First country in South Asia to join Indian Energy Exchange (IEX). Export 452 MW from 10 hydro projects.', 'NEA Annual Report 2021/22'),
(2023, 'India', 'Active', 'NVVN / PGCIL / IEX / PTC India', 'PEC / Day-Ahead / Medium Term Bilateral', 1346, 1833, NULL, NULL, NULL, NULL, 'Year Round', 'national_total_all_destinations_split_unverified', 'Medium term agreement: 200 MW to Haryana (May 2023). PTC India agreement 300 MW (June 2023). PEC tariff escalation 5.5%.', 'NEA Annual Report 2022/23'),
(2024, 'India', 'Active', 'NVVN / PGCIL / IEX / PTC India', 'PEC / Day-Ahead / Medium Term Bilateral', 1946, 1895, NULL, NULL, NULL, NULL, 'Year Round', 'national_total_all_destinations_split_unverified', 'Nepal became NET EXPORTER for first time. Export exceeded import by 51 GWh. Butwal-Gorakhpur 400kV line under implementation.', 'NEA Annual Report 2023/24'),
(2025, 'India', 'Active', 'NVVN / PGCIL / IEX / NTPC Vidhyut', 'PEC / Day-Ahead / Medium Term Bilateral', 2380, 1681, 17471, NULL, NULL, NULL, 'Year Round', 'national_total_all_destinations_split_unverified', 'Export revenue NRs 17,471 million (17.47 billion). Export up 22% from previous year. Nepal confirmed net exporter.', 'NEA Annual Report 2024/25'),
(2020, 'Bangladesh', 'No Trade', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'no_volume_reported', 'No electricity trade. Discussions at study stage only.', 'NEA Annual Report 2019/20'),
(2021, 'Bangladesh', 'No Trade', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'no_volume_reported', 'No electricity trade. COVID impacted cross-border discussions.', 'NEA Annual Report 2020/21'),
(2022, 'Bangladesh', 'No Trade', 'BPDB (planned)', 'Tripartite (planned)', NULL, NULL, NULL, NULL, 40, NULL, NULL, 'no_volume_reported', '40 MW export planned via Indian grid. Baharampur-Bheramara 400kV HVDC link discussed.', 'NEA Annual Report 2021/22'),
(2023, 'Bangladesh', 'Planned', 'BPDB / NVVN', 'Tripartite Agreement (finalizing)', NULL, NULL, NULL, NULL, 40, NULL, 'Monsoon (planned)', 'no_volume_reported', 'Tripartite agreement NEA+NVVN+BPDB in final stage. 40 MW via Baharampur-Bheramara HVDC. Wet season export planned.', 'NEA Annual Report 2022/23'),
(2024, 'Bangladesh', 'Planned', 'BPDB / NVVN', 'Tripartite Agreement (signing soon)', NULL, NULL, NULL, NULL, 40, NULL, 'Monsoon (planned)', 'no_volume_reported', 'Agreement to be signed soon. 4th JSC meeting Nepal-Bangladesh agreed to form JV for Sunkoshi III (683 MW).', 'NEA Annual Report 2023/24'),
(2025, 'Bangladesh', 'Active', 'BPDB / NVVN / India', 'Tripartite Agreement', NULL, NULL, NULL, NULL, 40, NULL, 'Monsoon only (June 15 - Oct 2025)', 'no_volume_reported', 'FIRST EVER export to Bangladesh. 40 MW started June 15 2025 via India transmission line. 5 month monsoon season. Tripartite signed October 2024.', 'NEA Annual Report 2024/25');
